const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a bounding box for Taiwan
  var taiwan = ee.Geometry.Rectangle([119.5, 21.5, 122.5, 25.5]);

  // Time periods as specified
  var period1_start = '2020-02-10';
  var period1_end = '2020-02-25';
  var period2_start = '2020-04-20';
  var period2_end = '2020-05-12';

  // 2. Data Acquisition
  // Get NO2 data from Sentinel-5P
  var no2_collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select(['tropospheric_NO2_column_number_density', 'qa_value']);

  // Filter for period 1
  var col1 = no2_collection
    .filterDate(period1_start, period1_end)
    .filterBounds(taiwan);

  // Filter for period 2
  var col2 = no2_collection
    .filterDate(period2_start, period2_end)
    .filterBounds(taiwan);

  // Check if collections are empty
  var col1_size = col1.size().getInfo();
  var col2_size = col2.size().getInfo();

  print('Period 1 (Feb 10-25) Images: ' + col1_size);
  print('Period 2 (Apr 20-May 12) Images: ' + col2_size);

  if (col1_size === 0 || col2_size === 0) {
    print('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Create mean composites with QA masking
  // Mask pixels with QA < 0.5 (lower quality)
  var maskLowQA = function(image) {
    var qa = image.select('qa_value');
    var no2 = image.select('tropospheric_NO2_column_number_density');
    var mask = qa.gte(0.5);  // Keep good quality pixels
    return no2.updateMask(mask);
  };

  var mean1 = col1.map(maskLowQA).mean();
  var mean2 = col2.map(maskLowQA).mean();

  // 4. Calculation - Get mean NO2 values and pixel counts
  var scale = 1000;  // 1km scale for efficiency

  var stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: scale,
    maxPixels: 1e9,
    bestEffort: true
  });

  var stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: scale,
    maxPixels: 1e9,
    bestEffort: true
  });

  var mean_no2_1 = stats1.get('tropospheric_NO2_column_number_density_mean').getInfo();
  var count1 = stats1.get('tropospheric_NO2_column_number_density_count').getInfo();
  var mean_no2_2 = stats2.get('tropospheric_NO2_column_number_density_mean').getInfo();
  var count2 = stats2.get('tropospheric_NO2_column_number_density_count').getInfo();

  // 5. Validation & Final Answer
  print('Period 1 Mean NO2: ' + (mean_no2_1 ? mean_no2_1.toFixed(6) : 'null') + 
        ' mol/m², Valid Pixels: ' + count1);
  print('Period 2 Mean NO2: ' + (mean_no2_2 ? mean_no2_2.toFixed(6) : 'null') + 
        ' mol/m², Valid Pixels: ' + count2);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // Check for invalid calculations
  if (mean_no2_1 === null || mean_no2_2 === null || 
      isNaN(mean_no2_1) || isNaN(mean_no2_2) ||
      mean_no2_1 < 0 || mean_no2_2 < 0 ||  // NO2 should be positive
      mean_no2_1 > 0.01 || mean_no2_2 > 0.01) {  // Unreasonably high
    print('<answer>C3</answer>');
    return;
  }

  // Compare the two periods
  var increase = mean_no2_2 > mean_no2_1;

  if (increase) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
